struct Counter {
    count: u32,
}

impl Counter {
    fn new() -> Self {
        Counter { count: 0 }
    }

    fn value(&self) -> u32 {
        self.count
    }

    fn bump(&mut self) {
        self.count += 1;
    }
}

fn main() {
    let mut c = Counter::new();
    c.bump();
    c.bump();
    println!("count = {}", c.value());
}

