exercise.solution:
struct Song {
    title: String,
    plays: u32,
}

impl Song {
    fn new(title: String) -> Self {
        Song { title, plays: 0 }
    }

    fn play(&mut self) {
        self.plays += 1;
    }
}

fn main() {
    let mut song = Song::new(String::from("echo"));
    song.play();
    song.play();
    println!("{} played {} times", song.title, song.plays);
}
